		long C = sc.nextLong();
		long D = sc.nextLong();
		long CD = C*D;
		long tempC = Math.max(C,D),tempD = Math.min(C,D);
		long r = tempC%tempD;
		while(r != 0) {
			tempC = tempD;
			tempD = r;
			r = tempC%tempD;
		}
		CD /= tempD;
		long t1 = B/C - (A/C);
		long t2 = B/D - (A/D);
		long t3 = B/CD - (A/CD);	
