import java.util.PriorityQueue;

public class Main {
	public static void main(String[] args) {
		FastScanner scan = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);
		int n = scan.nextInt();
		PriorityQueue<BigDecimal> v = new PriorityQueue<BigDecimal>();

		for (int i = 0; i < n; i++) {
			v.add(new BigDecimal(scan.nextInt()));
		}

		BigDecimal per = new BigDecimal(2);
		while (v.size() > 1) {
