    }

    private static long lcm(long a, long b) {
        return a * b / gcb(a, b);
    }

    private static long gcb(long a, long b) {
        if (a < b) return gcb(b, a);
        if (b == 0) return a;
        return gcb(b, a%b);
    }
}

