    static class CColoringColorfully {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            String s = in.next();
            int nbChanges = solve(s);
            out.println(nbChanges);
        }

        private int solve(String s) {
            return Math.min(solve(s, '0'), solve(s, '1'));
        }

        private int solve(String s, char cur) {
            int nbIfStart0 = 0;
            for (int i = 0; i < s.length(); i++) {
                if (s.charAt(i) != cur) {
                    nbIfStart0++;
                }
                cur = cur == '0' ? '1' : '0';
            }
            return nbIfStart0;
        }

    }
}

