	public static void main(String[] args) 
	{ 
		FastReader sc = new FastReader(); 
		int n = sc.nextInt();
      	long[] arr = new long[n+1], brr = new long[n];
      	long res = 0;
      	for(int i=0;i<=n;i++){
           	arr[i] = sc.nextLong();
          	res+=arr[i];
        }

      	for(int j=0;j<n;j++)
          	brr[j] = sc.nextLong();

      	for(int i=n-1;i>=0;i--){
          	long temp = Math.min(brr[i], arr[i+1]);
          	brr[i]-=temp;
          	arr[i+1]-=temp;
