        for (int num : data) {
            if (min > num) {
                min = num;

                if (min_profit <  min - max) {
                    min_profit = min - max;
                    max = min;
                } else {
                    max = Integer.MIN_VALUE;
                }
            } else if (count > 0 && max <= num) {
                max = num;
                if (ans < max - min)
                    ans = max - min;
            }
            count++;
       }
        System.out.println(ans > min_profit ? ans : min_profit);
    }
}

