        long max = 0;
        long sum = 0;
        long first = 0;
        long previous = 0;

        for (long i = 0; i < n; i++) {
            long a = scanner.nextLong();
            if (i == 0) {
                max = a;
                sum = a;
                first = a;
                previous = a;

            } else {
                long aida = a - previous;
