		int binarySearch(int[] array, int key) {			
			int pLeft = 0;		
			int pRight = array.length - 1;		

			int center = 0;		
			do {		
				center = (pLeft + pRight) / 2;	

				if (array[center] == key) {	
					return center;
				} else if (array[center] < key){	
					pLeft = center + 1; //真ん中の一つ右側を左端とする
				} else {	
					pRight = center - 1;
				}	
			} while (pLeft <= pRight);		
