public class Main {
    void solve(Scanner sc, PrintWriter pw) {
        int N = sc.nextInt();
        long total = 0;
        int currentMax = Integer.MIN_VALUE;
        for (int i = 0; i < N; i++) {
            int val = sc.nextInt();
            int nextMax = Math.max(currentMax, val);
            if (i > 0) {
                total += nextMax - val;
            }
            currentMax = nextMax;
        }
        pw.println(total);
    }
