class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    void solve() throws IOException {
      //  for (int T = ni();T>0;T--) {
            int d = ni(), t = ni(), s = ni();
            float temp = (float) d/(float) s;
            if(t >= temp)
                out.println("Yes");
