    static class TaskB {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            String[] s = new String[3];
            for (int i = 0; i < 3; i++)
                s[i] = in.next();
            int[] p = new int[3];
            int cp = 0;
            while (p[cp] < s[cp].length())
                cp = s[cp].charAt(p[cp]++) - 'a';
