    public static void dp(ArrayList<Integer> building){
        String st = "";
        for(int i = 0;i <= 29;i++){
            if(i <= 8){
                st += " " + building.get(i);
            }else if(i == 9){
                st += " " + building.get(i);
                System.out.println(st);
