                st += " " + building.get(i);
            }else if(i == 19){
                st += " " + building.get(i);
                System.out.println(st);
                st = "";
            }else if(i >= 20 && i <= 28){
                st += " " + building.get(i);
            }else if(i == 29){
                st += " " + building.get(i);
                System.out.println(st);
                st = "";
            }
        }
    }
}

