    static class CAttackSurvival {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();
            int q = in.nextInt();
            int a = k - q;
            int[] arr = new int[n];
            Arrays.fill(arr, a);
            for (int i = 0; i < q; i++) {
                int b = in.nextInt() - 1;
                arr[b]++;
            }
            for (int i = 0; i < n; i++) {
