            long n = in.nextInt();
            out.println(n + _F.powLLP(n, 2, IINF) + _F.powLLP(n, 3, IINF));
        }

    }

    static class _F {
        public static long powLLP(long x, long y, long p) {
            long res = 1;
            x = x % p;
            if (x == 0) return 0;
            while (y > 0) {
                if ((y & 1) == 1) {
                    res = (res % p * x % p) % p;
                }
                y = y >> 1;
                x = (x * x) % p;
            }
            return res;
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

