		double minutes = m / 60;

		double angle = 360;
		if(hour == 0) {
			angle *= 1 - minutes;
		}else if(minutes == 0) {
			angle *= 1 - hour;
		}else {
			angle *= hour < minutes ? minutes - hour : hour - minutes;
		}
