        if (x==n-1)return 0;
        if (memo[x]!=null){
            return memo[x];
        }
        int a=Integer.MAX_VALUE,b=Integer.MAX_VALUE;
        if (x+1<n)a=dp(x+1,n,h)+Math.abs(h[x]-h[x+1]);
        if (x+2<n)b=dp(x+2,n,h)+Math.abs(h[x]-h[x+2]);
