	static class Task {
		public void solve(int testNumber, InputReader in, PrintWriter out) {
			long n = in.nextLong();
			long ans = Long.MAX_VALUE;
			for (long i = 1; i <= Math.sqrt(n); i++) {
				long a = i;
				long b = n / i;
				if (a * b == n) {
					ans = Math.min(ans, (a - 1) + (b - 1));
				}
			}
			out.println(ans);
		}
	}

