			array[i][1] = sc.nextInt();
			array[i][2] = sc.nextInt();
		}
		int x=0,y=0,t=0,i;
		for(i=0;i<n;i++) {
			int sub = array[i][0]-t;
			if((x+y)%2==0 ) {
				if(sub%2==0) {
