public class Main {
  static InputReader in;
  static PrintWriter out;

  static class Solution {
    void solve() throws IOException {
      int N = in.nextInt();
      int cnt;
      int[] A = new int[N];
      for (int i = 0; i < N; i++) {
        A[i] = in.nextInt();
      }

      cnt = bubbleSort(A, N);

      for (int i = 0; i < N; i++) {
        out.print(A[i]);
        if (i != N - 1) {          
          out.print(" ");
        } else {
          out.print("\n");
        }
      }

      out.println(cnt);
//      End solve()
    }

    int bubbleSort(int[] A, int N) {
      int cnt = 0;

      boolean flg = true;
      while (flg) {
        flg = false;
        for (int i = N - 1; i > 0; i--) {
          if (A[i] < A[i - 1]) {
            int tmp = A[i];
            A[i] = A[i - 1];
            A[i - 1] = tmp;

            cnt++;
            flg = true;
          }
        }

      }
      return cnt;
    }

//  End solution
  } 


  public static void main(String[] args) throws IOException {
    in = new InputReader(System.in);
    out = new PrintWriter(System.out);
    Solution solver = new Solution();
    solver.solve();
    out.close();
