		for(int i=0;i<M;i++) {
			int p = sc.nextInt();
			String S = sc.next();
			if(S.equals("AC")) {
				if(!end[p]) {
					ac++;
					wa+=wa_t[p];
					end[p]=true;
				}
			}else if(S.equals("WA")) {
				if(!end[p]) {
					wa_t[p]++;
				}
			}else {
				throw new RuntimeException();
			}
		}
		out.println(ac+" "+wa);

	}
}

