                for(j=i+1;j<=k;j++)
                    dp[i][j]=dp[i][j-1];
            }
            else {
                for(j=1;j<=k;j++)
                    dp[i][j]=Math.min(dp[i][j-1], dp[i-j][k] + Math.abs(a[i-j]-a[i]));
