		if (r / 2019L != (l - 1) / 2019L) {
			out.println(0);
			return;
		}
		long i, j;
		long mi = 2019;
		for (i = l; i <= r; i++) {
			for (j = i + 1; j <= r; j++) {
				mi = Math.min(mi, ((i % 2019L) * (j % 2019L)) % 2019L);
			}
		}
		out.println(mi);
