        final int[] ia = split(input);

        int W = ia[0];
        int H = ia[1];
        int x = ia[2];
        int y = ia[3];
        int r = ia[4];

        int xMax = x + r;
        int yMax = y + r;
        int xMin = x - r;
        int yMin = y - r;

        if (xMax > W || yMax > H || xMin < 0 || yMin < 0) {
            return "No";
        }

        return "Yes";
    }

