public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		String w = sc.next();
		sc.close();
		Map<String, Integer> map = new HashMap<String, Integer> ();
		for(int i = 0; i < w.length(); i++) {
			String tmp = w.substring(i, i + 1);
