            long diff = average - num;
            long diff2 = (average + 1) - num;
            result += diff * diff;
            result2 += (diff2 * diff2);
        }
        out.println(Math.min(result, result2));

        out.close();
    }

    static class CF_Reader {
        BufferedReader br;
        StringTokenizer st;

        public CF_Reader() throws IOException {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine().trim());
            return st.nextToken();
        }

        long longNext() throws IOException {
            return Long.parseLong(next());
        }

        int intNext() throws IOException {
            return Integer.parseInt(next());
        }

        double doubleNext() throws IOException {
            return Double.parseDouble(next());
        }

        char charNext() throws IOException {
            return next().charAt(0);
        }

        public int[] nextIntArray(final int n) throws IOException {
            final int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = intNext();
            return a;
        }

        public long[] nextLongArray(final int n) throws IOException {
            final long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = longNext();
            return a;
        }

        String line() throws IOException {
            return br.readLine().trim();
        }
    }
}

import java.util.*;
 class Main {
    public static void main(String[] args) throws Exception{
        Scanner scan = new Scanner(System.in);
        String S = scan.next();
        String T = scan.next();
        boolean flag = stringMatching(S, T);
        if(flag){
            System.out.println("Yes");
        }else{
            System.out.println("No");
        }
    }
    public static boolean stringMatching(String S, String T){
        if(S.length() == T.length() || T.length() - S.length() > 1 || T.length() < S.length()){
            return false;
        }
        int i = 0;
        int j = 0;
        while(i < S.length()){
            if(S.charAt(i) != T.charAt(i)){
                return false;
            }
            i++;
            j++;
        }

        if(i == S.length() && j != T.length()){
            return true;
        }else{
            return false;
        }
    }
}

