public class Main {
    public static int maxCandies(int a[][], int i, int j, int sum) {
        if(i >= 2 || j >= a[0].length) {
            return 0;
        }
        if(i == 1 && j == a[0].length - 1)
            return a[i][j];
        sum += Math.max(a[i][j] + maxCandies(a, i+1, j, sum), a[i][j] + maxCandies(a, i, j+1, sum));
        return sum;
    }
