    static void solve() {
        int N = sc.nextInt();
        PriorityQueue<Double> que = new PriorityQueue<>();
        for (int i = 0; i < N; i++) {
            que.add(sc.nextDouble());
        }
        while (que.size() > 1) {
            double x = que.poll();
            double y = que.poll();
            que.add((x + y) / 2);
        }
        out.println(que.poll());
    }

    static void debug(Object... args) {
