class Main{

	static class FastReader {
		BufferedReader br;
		StringTokenizer st;

		public FastReader() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements()) {
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		long nextLong() {
			return Long.parseLong(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (IOException e) {
				e.printStackTrace();
			}
			return str;
		}
	}

	public static void main(String[] args) {
		FastReader sc = new FastReader();
		int a = sc.nextInt(),b=sc.nextInt(),c=sc.nextInt();
		int d1=Math.abs(b-a),d2=Math.min(Math.abs(b-a),Math.abs(c-a)),d3=Math.abs(c-b);
		int d4=Math.min(Math.abs(a-b), Math.abs(c-b)),d5=Math.abs(a-c);
		int d6=Math.min(Math.abs(a-c), Math.abs(b-c)),d7=Math.abs(a-b);
		System.out.println(Math.min(d2+d3, Math.min(d4+d5, d6+d7)));
	}
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int dishNum = sc.nextInt();

		ArrayList<Integer> eatOrder = new ArrayList<>();
		for(int i = 0; i < dishNum; i++) {
			eatOrder.add(sc.nextInt());
		}

		ArrayList<Integer> firstSatisfaction = new ArrayList<>();
		for(int i = 0; i < dishNum; i++) {
			firstSatisfaction.add(sc.nextInt());
		}

		ArrayList<Integer> secondSatisfaction = new ArrayList<>();
		for(int i = 0; i < dishNum-1; i++) {
			secondSatisfaction.add(sc.nextInt());
		}

		int result = 0;
		for(int i = 0; i < dishNum; i++) {
			int eatNum = eatOrder.get(i);
			result += firstSatisfaction.get(eatNum-1);

			if(i != dishNum-1) {
				int eatNumNext = eatOrder.get(i+1);
				if(eatNum+1 == eatNumNext) {
					result += secondSatisfaction.get(eatNum-1);
				}	
			}
		}

		System.out.println(result);
		sc.close();
	}
}

