	static class Solver
	{
        void solve(IO io, PrintWriter out)
        {
            int t = 1;
            while(t-->0)
            {
                int n = io.nextInt();
              	int[] ar = new int[n];
              	for(int i=0 ; i<n ; i++)
                  ar[i] = io.nextInt();
              	int dp[] = new int[n];
              	Arrays.fill(dp,Integer.MAX_VALUE);
              	dp[0]=0;
              	int end=0;
              	for( ; end<n-1; end++)
                {
                  dp[end+1] = Math.min(dp[end+1],dp[end]+Math.abs(ar[end]-ar[end+1]));
                  if(end+2<n)
                  	dp[end+2] = Math.min(dp[end+2],dp[end]+Math.abs(ar[end]-ar[end+2]));
                  //out.println(dp[end]);
                }
              	out.print(dp[n-1]);
            }
	    }
	}
