    static class BGreatOceanView {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();

            int max = Integer.MIN_VALUE;
            int answer = 0;
            for (int i = 0; i < n; i++) {
                int h = in.nextInt();

                if (h >= max) {
                    answer++;
                    max = h;
                }
            }

            out.println(answer);
        }

    }

