class Solver {
	Scanner sc;
	PrintWriter out;
    public Solver(InputStream in, PrintWriter out) {
    	sc = new Scanner(in);
    	this.out = out;
    }
    // ==================================================================
    long INF = 999999999999L;
    public void solve() {
    	long N = Long.parseLong(sc.next());
    	long ans = INF;
    	for (long i = 2; i * i <= N; i++) {
			if(N % i == 0) {
				ans = Math.min(ans, (i - 1) + (N / i - 1));
			}
		}
    	if(ans == INF)	ans = N - 1;
    	out.println(ans);
    }
}

