			}
			BigDecimal x2 = new BigDecimal(a + 1).divide(new BigDecimal("0.08"), 0, BigDecimal.ROUND_FLOOR);
			if(new BigDecimal(a + 1).remainder(new BigDecimal("0.08")).equals(BigDecimal.ZERO)) {
				x2 = x2.subtract(BigDecimal.ONE);
			}
