            System.out.println(o);
    }

    static Object run() {
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();
            ArrayList<Integer> a = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                a.add(sc.nextInt());
            }
            long latest = 0;
            long result = 0;
            for (int i = 0; i < n; i++) {
                if (latest > a.get(i)) {
