public class Main {
  public static void main(String [] args) {
    System.out.println(solve());
  }

  public static long solve() {
    FastReader fr = new FastReader();
    int N = fr.nextInt();
    int[] d = new int[N];
    long sum = 0;
    long result = 0;
    for (int i = 0; i < N; i++) {
      d[i] = fr.nextInt();
      sum += d[i];
    }

    for (int i = 0; i < N-1; i++) {
      sum -= d[i];
      result += d[i] * sum;
    }

	return result;
  }
}

