class AtCoder {

    final int N;
    int[] d;

    AtCoder(FastScanner sc) {
        N = sc.nextInt();
        d = new int[N];
        for (int i = 0; i < N; i++) {
            d[i] = sc.nextInt();
        }
    }

    void solve(PrintWriter out) {
        int sum = 0;
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                sum += d[i] * d[j];
            }
        }
        out.println(sum);
    }

